(()=>{const h=document.querySelector('main>header,main>.tools-top');if(!h||h.querySelector('[data-lightcc-manage]'))return;const a=document.createElement('a');a.href='/lightcc.html';a.textContent='LightCC 管理';a.dataset.lightccManage='1';a.style.cssText='display:inline-block;margin-left:12px;padding:9px 14px;border:1px solid #58786e;border-radius:8px;color:#b8e3d3;text-decoration:none;white-space:nowrap';h.append(a)})();
